const documents = [];

for (const item of $input.all()) {

  // Extract and parse the actual JSON generated by Gemini
  const meeting = JSON.parse(item.json.content.parts[0].text);

  for (const framework of meeting.frameworks) {

    const content = [
      `Framework: ${framework.name}`,
      `Problem:\n${framework.problem}`,

      `Principles:\n${framework.principles
        .map(p => `- ${p}`)
        .join('\n')}`,

      `Method:\n${framework.method
        .map((step, index) => `${index + 1}. ${step}`)
        .join('\n')}`,

      `Diagnostic Questions:\n${framework.diagnostic_questions
        .map(q => `- ${q}`)
        .join('\n')}`,

      `Recommended Actions:\n${framework.recommended_actions
        .map(a => `- ${a}`)
        .join('\n')}`,

      `Expected Outcome:\n${framework.expected_outcome}`,

      `Additional Coaching Insights:\n${(meeting.additional_coaching_insights || [])
        .map(i => `- ${i}`)
        .join('\n')}`
    ].join('\n\n');

    documents.push({
      json: {
        session_id: meeting.meeting_id,
        stream_type: 'framework',
        content: content,
        metadata: {
          framework_name: framework.name
        }
      }
    });
  }
}

return documents;

const inputItem = $input.first();
const meetings = inputItem.json.data;

return meetings.map(meeting => {
  const transcript = meeting.transcript;

  const sampledTranscript = transcript.length <= 60
    ? transcript
    : [
        ...transcript.slice(0, 40),
        ...transcript.slice(-20)
      ];

  return {
    json: {
      ...meeting,
      sampled_transcript: sampledTranscript,
      original_turn_count: transcript.length,
      sampled_turn_count: sampledTranscript.length
    }
  };
});

