const id = current.meeting_id;
const data = $('Extract from File').item.json.data;
const result = {}
for(const meeting of data){
  if(meeting.id === id){
    result.id = id;
    result.title = meeting.title;
    result.participants = meeting.participants;
    result.transcript = meeting.transcript;
    result.meeting_type = current.meeting_type;
    result.summary = current.summary;
    result.confidence_score = current.confidence_score;
  }
}
return result;

