const embeddings = $input.all();
const documents = $('Code in JavaScript2').all();

// Make sure every document has a corresponding embedding
if (embeddings.length !== documents.length) {
  throw new Error('Document and embedding counts do not match');
}

return embeddings.map((item, index) => {
  return {
    json: {
      ...documents[index].json,
      embedding: item.json.embedding.values
    }
  };
});

const meetings = $input.all();

const documents = [];

for (const item of meetings) {
  const meeting = item.json;

  // Identify Dr. Sara from the participant list
  const coach = meeting.participants.find(
    person => person.name === 'Dr. Sara Hegy'
  );

  if (!coach) continue;

  // Extract only Dr. Sara's original words
  const coachDialogue = meeting.transcript
    .filter(turn => turn.speaker === coach.name)
    .map(turn => turn.text);

  // Combine dialogue into chunks
  let chunk = '';

  for (const sentence of coachDialogue) {
    const nextChunk = chunk
      ? chunk + '\n' + sentence
      : sentence;

    if (nextChunk.length > 700 && chunk.length > 0) {
      documents.push({
        json: {
          session_id: meeting.id,
          stream_type: 'voice_sample',
          content: chunk,
          metadata: {
            coach: coach.name,
            source: 'verbatim_transcript'
          }
        }
      });

      chunk = sentence;
    } else {
      chunk = nextChunk;
    }
  }

  // Save the remaining dialogue
  if (chunk) {
    documents.push({
      json: {
        session_id: meeting.id,
        stream_type: 'voice_sample',
        content: chunk,
        metadata: {
          coach: coach.name,
          source: 'verbatim_transcript'
        }
      }
    });
  }
}

return documents;

