if (embeddings.length !== documents.length) {
  throw new Error('Document and embedding counts do not match');
}

return embeddings.map((item, index) => ({
  json: {
    ...documents[index].json,
    embedding: item.json.embedding.values
  }
}));

const rejected = $input.all();

// Get all original meetings from the Extract from File node
const originalMeetings = $('Extract from File').first().json.data;

return rejected.map(item => {
  // Parse Gemini's classification result
  const classification = JSON.parse(
    item.json.content.parts[0].text
  );

  // Find the original meeting using its ID
  const original = originalMeetings.find(
    meeting => meeting.id === classification.meeting_id
  );

  if (!original) {
    throw new Error(
      `Original meeting not found: ${classification.meeting_id}`
    );
  }

  const rejectionReason =
    classification.meeting_type !== 'Client Coaching'
      ? 'Meeting type is not Client Coaching'
      : classification.confidence_score < 0.80
        ? 'Confidence score is below 0.80'
        : 'Rejected by ingestion firewall';

  return {
    json: {
      session_id: classification.meeting_id,
      title: original.title,
      meeting_type: classification.meeting_type,
      confidence_score: classification.confidence_score,
      summary: classification.summary,
      rejection_reason: rejectionReason,
      metadata: {
        participants: original.participants,
        created_at: original.created_at
      }
    }
  };
});
